## Land power: share of holdings vs share of area


::: {.cell}

```{.r .cell-code}
share_l <- melt(land, id.vars = c("Survey_Round", "Year", "Group"),
                measure.vars = c("h_share", "a_share"),
                variable.name = "Metric", value.name = "Share")
share_l[, Metric := fifelse(Metric == "h_share", "Share of holdings", "Share of operated area")]
share_l[, Round := factor(Survey_Round, levels = ROUNDS)]
share_l[, tip := sprintf("%s | %s\n%s: %.1f%%", Survey_Round, Group, Metric, 100 * Share)]

p_power <- ggplot(share_l, aes(x = Group, y = Share, fill = Metric)) +
  geom_col(position = position_dodge(width = 0.8), width = 0.7) +
  geom_text_interactive(aes(label = sprintf("%.0f%%", 100 * Share), data_id = paste(Survey_Round, Group, Metric), tooltip = tip),
                        position = position_dodge(width = 0.8), vjust = -0.4, size = 2.8) +
  facet_wrap(~ Round, nrow = 1) +
  scale_y_continuous(breaks = PCT_BREAKS, labels = PCT_LABELS) +
  scale_fill_manual(values = c("Share of holdings" = "#A8C3D6",
                               "Share of operated area" = "#1B4F7A")) +
  labs(title = "Share of holdings and share of operated area by size group",
       x = NULL, y = NULL, fill = NULL,
       caption = "Source: Input Survey Table 1A.") +
  theme(axis.text.x = element_text(angle = 30, hjust = 1, size = 8))

girafe(ggobj = p_power, width_svg = 10, height_svg = 5,
       options = list(opts_tooltip(css = TIP_CSS),
                      opts_hover(css = "opacity:0.6;"),
                      opts_toolbar(position = "topright")))
