## Irrigation divide: heatmap


::: {.cell}

```{.r .cell-code}
irr[, Round := factor(Survey_Round, levels = ROUNDS)]
irr[, Group := factor(Group, levels = GROUP_LEVELS)]
irr[, tip := sprintf("%s | %s\nIrrigated share of sown area: %.1f%%",
                     Survey_Round, Group, 100 * Irr_share)]
irr[, lab := sprintf("%.0f%%", 100 * Irr_share)]

p_irr <- ggplot(irr, aes(x = Round, y = Group, fill = Irr_share)) +
  geom_tile(colour = "white") +
  geom_text_interactive(aes(label = lab, data_id = paste(Survey_Round, Group, "label"),
                            tooltip = tip), size = 3.4, colour = "grey10") +
  scale_fill_gradient(low = "#F3E9D2", high = "#1B4F7A", name = "Irrigated share") +
  scale_y_discrete(limits = rev(GROUP_LEVELS)) +
  labs(title = "Irrigated share of net sown area by size group and round",
       x = "Survey round", y = NULL,
       caption = "Source: Input Survey Table 1A. Share = irrigated / (irrigated + unirrigated).")

girafe(ggobj = p_irr, width_svg = 8.5, height_svg = 4.8,
       options = list(opts_tooltip(css = TIP_CSS),
                      opts_hover(css = "opacity:0.7;"),
                      opts_toolbar(position = "topright")))
```

