## Fertiliser coverage by regime


::: {.cell}

```{.r .cell-code}
fert_plot <- fert[Regime %chin% c("Irrigated", "Unirrigated")]
fert_plot[, Group := factor(Group, levels = GROUP_LEVELS)]
fert_plot[, tip := sprintf("%s | %s | %s\nArea treated: %.1f%% of gross cropped area",
                           Survey_Round, Group, Regime, 100 * Coverage)]

p_fert <- ggplot(fert_plot, aes(x = Year, y = Coverage, colour = Regime)) +
  geom_line(aes(group = paste(Group, Regime))) +
  geom_point_interactive(aes(data_id = paste(Survey_Round, Group, Regime), tooltip = tip),
                         size = 2.6) +
  facet_wrap(~ Group, nrow = 1) +
  scale_colour_manual(values = c("Irrigated" = "#1B4F7A", "Unirrigated" = "#D1603D")) +
  scale_y_continuous(breaks = PCT_BREAKS, labels = PCT_LABELS) +
  scale_x_continuous(breaks = c(1996, 2006, 2016)) +
  labs(title = "Fertiliser coverage by size group and irrigation regime",
       x = "Survey year (start of round)", y = "Area treated, % of gross cropped area",
       colour = NULL,
       caption = "Source: Input Survey Table 2A.") +
  theme(axis.text.x = element_text(size = 8))

girafe(ggobj = p_fert, width_svg = 10, height_svg = 4.8,
       options = list(opts_tooltip(css = TIP_CSS),
                      opts_hover(css = "opacity:0.6;"),
                      opts_toolbar(position = "topright")))
```

