## Average farm size over time


::: {.cell}

```{.r .cell-code}
land[, Group := factor(Group, levels = GROUP_LEVELS)]
land[, tip := sprintf("%s | %s\nAverage size: %.2f ha", Survey_Round, Group, avg_size)]

p_size <- ggplot(land, aes(x = Year, y = avg_size, colour = Group)) +
  geom_line(aes(group = Group)) +
  geom_point_interactive(aes(data_id = paste(Survey_Round, Group), tooltip = tip), size = 2.8) +
  scale_y_log10() +
  scale_x_continuous(breaks = c(1996, 2001, 2006, 2011, 2016)) +
  labs(title = "Average operated area per holding, by size group (log scale)",
       x = "Survey year (start of round)", y = "Average size (ha, log scale)",
       colour = NULL,
       caption = "Source: Input Survey Table 1A.")

girafe(ggobj = p_size, width_svg = 8.5, height_svg = 4.8,
       options = list(opts_tooltip(css = TIP_CSS),
                      opts_hover(css = "opacity:0.6;"),
                      opts_toolbar(position = "topright")))
```

